"SELECT DISTINCT\r\nCLAIM_ID,\r\n[Claim Billed Amount]\tAS \"Original Claim Billed Amount\",\r\n[Claim UCR] \tAS \"Original Claim UCR\",\r\n[Claim Allowed Amount]\tAS \"Original Claim Allowed Amount\",\r\n[Claim Deductible]\tAS \"Original Claim Deductible\",\r\n[Claim Copay/Coinsurance]\tAS \"Original Claim Copay/Coinsurance\",\r\n[Claim Sequestration]  \tAS \"Original Claim Sequestration\",\r\n[Claim Capitation]    AS \"Original Claim Capitation\",\r\n[Claim Interest Amount]    AS \"Original Claim Interest Amount\" ,\r\n[Claim Paid Amount]\tAS \"Original Claim Paid Amount\"\r\nFROM [Claim Amount]\r\n\r\nUNION ALL\r\n\r\nSELECT DISTINCT\r\nNULL    AS CLAIM_ID,\r\nCAST(NULL AS DOUBLE)\tAS \"Original Claim Billed Amount\",\r\nCAST(NULL AS DOUBLE) \tAS \"Original Claim UCR\",\r\nCAST(NULL AS DOUBLE)\tAS \"Original Claim Allowed Amount\",\r\nCAST(NULL AS DOUBLE)\tAS \"Original Claim Deductible\",\r\nCAST(NULL AS DOUBLE)\tAS \"Original Claim Copay/Coinsurance\",\r\nCAST(NULL AS DOUBLE)  \tAS \"Original Claim Sequestration\",\r\nCAST(NULL AS DOUBLE)    AS \"Original Claim Capitation\",\r\nCAST(NULL AS DOUBLE)    AS \"Original Claim Interest Amount\" ,\r\nCAST(NULL AS DOUBLE)\tAS \"Original Claim Paid Amount\"\r\nFROM [Claim Amount]"
